-- minmax
SELECT MIN(`loan_id`), MAX(`loan_id`), SUM(CASE WHEN `loan_id` IS NULL THEN 1 ELSE 0 END), COUNT(*) FROM `analytics.loans` WHERE (status <> 'TEST')

-- count_sampled
SELECT COUNT(*) FROM `analytics.loans` WHERE (status <> 'TEST') AND MOD(DIV(CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N'))), 18)) AS INT64), 1048576), 10000) < 500

-- duplicate_keys
SELECT COUNT(*) FROM (SELECT `loan_id` FROM `analytics.loans` WHERE (status <> 'TEST') GROUP BY `loan_id` HAVING COUNT(*) > 1) d

-- range_checksum_level0
SELECT DIV(rk - (1), 16384) AS b, COUNT(*) AS n, SUM(CAST(h AS NUMERIC)) AS s FROM (SELECT CAST(`loan_id` AS INT64) AS rk, CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N') || '|' || COALESCE('V' || FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)), 'N') || '|' || COALESCE('V' || FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST(`status` AS STRING)), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST(`ref` AS STRING)), 'N') || '|' || COALESCE('V' || CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END, 'N') || '|' || COALESCE('V' || FORMAT_DATE('%Y-%m-%d', `opened`), 'N') || '|' || COALESCE('V' || FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)), 'N') || '|' || COALESCE('V' || FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC'), 'N') || '|' || COALESCE('V' || SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23), 'N'))), 18)) AS INT64) AS h FROM `analytics.loans` WHERE (status <> 'TEST') AND (`loan_id` >= 1 AND `loan_id` <= 1000000)) t GROUP BY 1

-- range_checksum_level1
SELECT DIV(rk - (1), 512) AS b, COUNT(*) AS n, SUM(CAST(h AS NUMERIC)) AS s FROM (SELECT CAST(`loan_id` AS INT64) AS rk, CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N') || '|' || COALESCE('V' || FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)), 'N') || '|' || COALESCE('V' || FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST(`status` AS STRING)), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST(`ref` AS STRING)), 'N') || '|' || COALESCE('V' || CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END, 'N') || '|' || COALESCE('V' || FORMAT_DATE('%Y-%m-%d', `opened`), 'N') || '|' || COALESCE('V' || FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)), 'N') || '|' || COALESCE('V' || FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC'), 'N') || '|' || COALESCE('V' || SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23), 'N'))), 18)) AS INT64) AS h FROM `analytics.loans` WHERE (status <> 'TEST') AND ((`loan_id` >= 1 AND `loan_id` < 32769) OR (`loan_id` >= 114689 AND `loan_id` < 131073))) t GROUP BY 1

-- range_fetch
SELECT CAST(`loan_id` AS STRING) AS c0, FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)) AS c1, FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)) AS c2, NULLIF(RTRIM(CAST(`status` AS STRING)), '') AS c3, LOWER(CAST(`ref` AS STRING)) AS c4, CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END AS c5, CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END AS c6, FORMAT_DATE('%Y-%m-%d', `opened`) AS c7, FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)) AS c8, FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC') AS c9, SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23) AS c10 FROM `analytics.loans` WHERE (status <> 'TEST') AND ((`loan_id` >= 161 AND `loan_id` < 193) OR (`loan_id` >= 641 AND `loan_id` < 657))

-- hash_checksum_level0
SELECT MOD(kh, 64) AS b, COUNT(*) AS n, SUM(CAST(h AS NUMERIC)) AS s FROM (SELECT CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N'))), 18)) AS INT64) AS kh, CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N') || '|' || COALESCE('V' || FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)), 'N') || '|' || COALESCE('V' || FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST(`status` AS STRING)), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST(`ref` AS STRING)), 'N') || '|' || COALESCE('V' || CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END, 'N') || '|' || COALESCE('V' || FORMAT_DATE('%Y-%m-%d', `opened`), 'N') || '|' || COALESCE('V' || FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)), 'N') || '|' || COALESCE('V' || FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC'), 'N') || '|' || COALESCE('V' || SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23), 'N'))), 18)) AS INT64) AS h FROM `analytics.loans` WHERE (status <> 'TEST')) t GROUP BY 1

-- hash_checksum_level1_sampled
SELECT MOD(kh, 2048) AS b, COUNT(*) AS n, SUM(CAST(h AS NUMERIC)) AS s FROM (SELECT CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N'))), 18)) AS INT64) AS kh, CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N') || '|' || COALESCE('V' || FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)), 'N') || '|' || COALESCE('V' || FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)), 'N') || '|' || COALESCE('V' || NULLIF(RTRIM(CAST(`status` AS STRING)), ''), 'N') || '|' || COALESCE('V' || LOWER(CAST(`ref` AS STRING)), 'N') || '|' || COALESCE('V' || CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END, 'N') || '|' || COALESCE('V' || CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END, 'N') || '|' || COALESCE('V' || FORMAT_DATE('%Y-%m-%d', `opened`), 'N') || '|' || COALESCE('V' || FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)), 'N') || '|' || COALESCE('V' || FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC'), 'N') || '|' || COALESCE('V' || SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23), 'N'))), 18)) AS INT64) AS h FROM `analytics.loans` WHERE (status <> 'TEST')) t WHERE MOD(DIV(kh, 1048576), 10000) < 500 AND MOD(kh, 64) IN (3, 9) GROUP BY 1

-- hash_fetch
SELECT c0, c1, c2, c3, c4, c5, c6, c7, c8, c9, c10 FROM (SELECT CAST(`loan_id` AS STRING) AS c0, FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)) AS c1, FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)) AS c2, NULLIF(RTRIM(CAST(`status` AS STRING)), '') AS c3, LOWER(CAST(`ref` AS STRING)) AS c4, CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END AS c5, CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END AS c6, FORMAT_DATE('%Y-%m-%d', `opened`) AS c7, FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)) AS c8, FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC') AS c9, SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23) AS c10, CAST(CONCAT('0x', SUBSTR(TO_HEX(MD5(COALESCE('V' || CAST(`loan_id` AS STRING), 'N'))), 18)) AS INT64) AS kh FROM `analytics.loans` WHERE (status <> 'TEST')) t WHERE MOD(kh, 2048) IN (67, 131)

-- join_diff
SELECT l.c0, l.c1, l.c2, l.c3, l.c4, l.c5, l.c6, l.c7, l.c8, l.c9, l.c10, r.c0, r.c1, r.c2, r.c3, r.c4, r.c5, r.c6, r.c7, r.c8, r.c9, r.c10, l.j0, r.j0 FROM (SELECT CAST(`loan_id` AS STRING) AS c0, FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)) AS c1, FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)) AS c2, NULLIF(RTRIM(CAST(`status` AS STRING)), '') AS c3, LOWER(CAST(`ref` AS STRING)) AS c4, CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END AS c5, CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END AS c6, FORMAT_DATE('%Y-%m-%d', `opened`) AS c7, FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)) AS c8, FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC') AS c9, SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23) AS c10, COALESCE('V' || CAST(`loan_id` AS STRING), 'N') AS j0 FROM `analytics.loans` WHERE (status <> 'TEST')) l FULL OUTER JOIN (SELECT CAST(`loan_id` AS STRING) AS c0, FORMAT('%.2f', ROUND(CAST(`amount` AS BIGNUMERIC), 2)) AS c1, FORMAT('%.6f', ROUND(CAST(`rate` AS BIGNUMERIC), 6)) AS c2, NULLIF(RTRIM(CAST(`status` AS STRING)), '') AS c3, LOWER(CAST(`ref` AS STRING)) AS c4, CASE WHEN `active` THEN 'true' WHEN NOT `active` THEN 'false' END AS c5, CASE WHEN `flag` THEN '1' WHEN NOT `flag` THEN '0' END AS c6, FORMAT_DATE('%Y-%m-%d', `opened`) AS c7, FORMAT_DATETIME('%Y-%m-%d %H:%M:%E6S', DATETIME(`booked`)) AS c8, FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', `created_at`, 'UTC') AS c9, SUBSTR(FORMAT_TIMESTAMP('%Y-%m-%d %H:%M:%E6S', TIMESTAMP(`updated_at`, 'Asia/Singapore'), 'UTC'), 1, 23) AS c10, COALESCE('V' || CAST(`loan_id` AS STRING), 'N') AS j0 FROM `analytics.loans` WHERE (status <> 'TEST')) r ON l.j0 = r.j0 WHERE l.j0 IS NULL OR r.j0 IS NULL OR COALESCE('V' || l.c1, 'N') <> COALESCE('V' || r.c1, 'N') OR COALESCE('V' || l.c2, 'N') <> COALESCE('V' || r.c2, 'N') OR COALESCE('V' || l.c3, 'N') <> COALESCE('V' || r.c3, 'N') OR COALESCE('V' || l.c4, 'N') <> COALESCE('V' || r.c4, 'N') OR COALESCE('V' || l.c5, 'N') <> COALESCE('V' || r.c5, 'N') OR COALESCE('V' || l.c6, 'N') <> COALESCE('V' || r.c6, 'N') OR COALESCE('V' || l.c7, 'N') <> COALESCE('V' || r.c7, 'N') OR COALESCE('V' || l.c8, 'N') <> COALESCE('V' || r.c8, 'N') OR COALESCE('V' || l.c9, 'N') <> COALESCE('V' || r.c9, 'N') OR COALESCE('V' || l.c10, 'N') <> COALESCE('V' || r.c10, 'N')

-- columns
SELECT column_name, data_type, NULL, NULL, is_nullable FROM `analytics`.INFORMATION_SCHEMA.COLUMNS WHERE table_name = 'loans' ORDER BY ordinal_position

